"use client";

import Image from "next/image";

import { Tilt } from "@/components/motion/tilt";

/**
 * The hero's product window: a real screenshot of the console, not a replica.
 *
 * The file under it is generated by `npm run shots`, which drives the running
 * app and photographs `/app`. That is the whole point — a hand-built mock of
 * your own product drifts the moment the product moves, and drifts silently,
 * because nothing links the two files. This cannot: it is the product.
 *
 * The light console — the one a shopkeeper actually meets, and now also the one
 * the page around it is dressed as, so the violet carries straight through from
 * the hero into the window. The night console is captured too
 * (`dashboard-dark.png`) for anywhere that wants to show the 11pm till.
 */

/** Viewport 1280×820 at 2x, straight from `scripts/shots.mjs`. */
const SHOT = {
  src: "/shots/dashboard-light.png",
  width: 2560,
  height: 1640,
};

export function DashboardShot() {
  return (
    <Tilt max={4} className="relative" spotlight={false}>
      {/* Bloom behind the window, so it reads as lit rather than pasted on. */}
      <div
        aria-hidden
        className="glow inset-x-8 -bottom-10 top-16 bg-iris-600/20 blur-[80px]"
      />

      <div className="panel rim relative overflow-hidden rounded-[20px] shadow-[0_50px_120px_-50px_rgb(33_21_102/0.28)] sm:rounded-[26px]">
        <Image
          src={SHOT.src}
          width={SHOT.width}
          height={SHOT.height}
          // The hero is the largest paint on the page; it should not wait for
          // the lazy-loading observer to decide it is visible.
          priority
          sizes="(min-width: 1024px) 980px, 100vw"
          className="block h-auto w-full"
          alt="The Flo dashboard: sales, profit, cost of goods and margin for the last seven days, with a sales-and-profit chart, the split by category, top sellers and the most recent receipts."
        />
      </div>
    </Tilt>
  );
}
